package com.dimitriazzarone.chatgptmessenger;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.webkit.*;import android.widget.*;import android.view.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.zip.*;import org.json.*;

public class MainActivity extends Activity {
 WebView web;TextView status;boolean reading;int attempt;String taskUrl="",mode="",text="",title="Diari";final Handler handler=new Handler(Looper.getMainLooper());
 boolean trusted(String u){try{Uri x=Uri.parse(u);return "https".equals(x.getScheme())&&"chatgpt.com".equals(x.getHost());}catch(Exception e){return false;}}
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(3,13,26));setContentView(root);
 if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets s=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(s.left,s.top,s.right,s.bottom);return i;});}
 TextView name=new TextView(this);name.setText("DAN HEWA · DIARI SPECIAL EDITION");name.setTextColor(Color.CYAN);name.setPadding(12,12,12,8);root.addView(name);
 TextView info=new TextView(this);info.setText("Accedi e apri la chat dei diari. Copia la chat negli appunti, poi incollala in una nuova chat.");info.setTextColor(Color.WHITE);root.addView(info);
 LinearLayout row=new LinearLayout(this);root.addView(row);add(row,"Copia tutta la chat","copy");add(row,"Salva Word","save");add(row,"Condividi Word","share");
 status=new TextView(this);status.setTextColor(Color.CYAN);status.setText("Creato da Dimitri Azzarone · 1.0");root.addView(status);
 web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));web.setBackgroundColor(Color.rgb(3,13,26));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();String h=u.getHost();if("https".equals(u.getScheme())&&("chatgpt.com".equals(h)||"auth.openai.com".equals(h)||"auth0.openai.com".equals(h)))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}@Override public void onPageStarted(WebView v,String u,android.graphics.Bitmap icon){if(reading){attempt++;reading=false;status.setText("Pagina cambiata: ripeti la lettura.");}}});
 if(b==null||web.restoreState(b)==null)web.loadUrl("https://chatgpt.com/");}
 void add(LinearLayout row,String label,String action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setOnClickListener(v->read(action));row.addView(b,new LinearLayout.LayoutParams(0,-2,1));}
 String asset(){try(InputStream i=getAssets().open("diary-export.js")){ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=i.read(b))!=-1)o.write(b,0,n);return o.toString("UTF-8");}catch(Exception e){return "";}}
 void read(String action){if(reading)return;if(!trusted(web.getUrl())){status.setText("Apri la chat dei diari su ChatGPT.");return;}mode=action;taskUrl=web.getUrl();reading=true;int token=++attempt;status.setText("Lettura della cronologia…");web.evaluateJavascript(asset()+";window.__diaryStart();",null);poll(token,0);}
 void poll(int token,int ticks){handler.postDelayed(()->{if(isFinishing()||token!=attempt)return;if(!trusted(web.getUrl())||!taskUrl.equals(web.getUrl())){reading=false;status.setText("Chat cambiata: ripeti.");return;}if(ticks>65){reading=false;status.setText("Lettura scaduta. Riprova.");return;}web.evaluateJavascript("JSON.stringify(window.__diaryResult||{pending:true})",raw->{if(token!=attempt||!taskUrl.equals(web.getUrl())){reading=false;status.setText("Chat cambiata: ripeti.");return;}try{Object value=new JSONTokener(raw).nextValue();JSONObject result=new JSONObject((String)value);if(result.optBoolean("pending")){poll(token,ticks+1);return;}reading=false;if(result.has("error")){status.setText(result.getString("error"));return;}text=result.getString("text");title=result.optString("title","Diari");String summary=result.getInt("count")+" messaggi letti";status.setText(summary);if(!result.optBoolean("complete"))new AlertDialog.Builder(this).setTitle("Esportazione parziale").setMessage(result.optString("warning")+"\n\n"+summary).setNegativeButton("Annulla",null).setPositiveButton("Usa estratto",(d,w)->finishRead()).show();else finishRead();}catch(Exception e){reading=false;status.setText("Lettura non riuscita. Riprova.");}});},500);}
 void finishRead(){if("copy".equals(mode)){if(text.getBytes(StandardCharsets.UTF_8).length>650000){status.setText("Chat troppo grande per gli appunti Android: usa Salva Word.");return;}((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText(title,text));status.setText("Diari copiati negli appunti.");}else if("save".equals(mode)){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/vnd.openxmlformats-officedocument.wordprocessingml.document").putExtra(Intent.EXTRA_TITLE,"Diari.docx");startActivityForResult(i,7);}else share();}
 static String xml(String s){return s.replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]","").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
 static void entry(ZipOutputStream z,String name,String data)throws Exception{z.putNextEntry(new ZipEntry(name));z.write(data.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
 static void docx(OutputStream out,String title,String text)throws Exception{try(ZipOutputStream z=new ZipOutputStream(out)){entry(z,"[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/></Types>");entry(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>");StringBuilder body=new StringBuilder("<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body>");for(String line:(title+"\n\n"+text).split("\n",-1))body.append("<w:p><w:r><w:t xml:space=\"preserve\">").append(xml(line)).append("</w:t></w:r></w:p>");body.append("</w:body></w:document>");entry(z,"word/document.xml",body.toString());}}
 void share(){try{File dir=new File(getCacheDir(),"exports");dir.mkdirs();File f=new File(dir,"Diari.docx");docx(new FileOutputStream(f),title,text);Uri uri=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".files",f);Intent i=new Intent(Intent.ACTION_SEND).setType("application/vnd.openxmlformats-officedocument.wordprocessingml.document").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newUri(getContentResolver(),"Diari",uri));startActivity(Intent.createChooser(i,"Apri o salva con Drive / Documenti"));}catch(Exception e){status.setText("Condivisione non disponibile.");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==7&&result==RESULT_OK&&data!=null&&data.getData()!=null){try{docx(getContentResolver().openOutputStream(data.getData(),"wt"),title,text);status.setText("Documento Word salvato.");}catch(Exception e){status.setText("Salvataggio non riuscito.");}}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);web.saveState(b);}
 @Override protected void onDestroy(){attempt++;handler.removeCallbacksAndMessages(null);web.destroy();super.onDestroy();}
}
